"""Bootstrap of the .pyz (generated by ./pyt build ... --method pyz). Standard library only.

Python cannot import extensions (.pyd/.so) from inside a zip, so the first time the
contents are extracted to a cache versioned per build and run from there. If this interpreter
and OS have their own build (_pyz.json "targets": binaries, or dependencies that differ per
platform, whose extension ABI, "abi", must be this interpreter's: PyPy 8 is no PyPy 7.3, and
whose wheels' C library and oldest glibc or macOS, "floor", this machine's: musl is no glibc),
it is used; otherwise the pure Python version is used (if the app allows it).

Executables (an app's helper script, a dependency's binary) keep their x bit.

Cache: %LOCALAPPDATA%, ~/Library/Caches, $XDG_CACHE_HOME or ~/.cache, then
<name>/pyz/<build_id>/<key|pure>/. It keeps the most recently started builds plus every
build started in the last day, and never deletes a build that is still running (each start
holds a lock in its build folder until it ends); deleting the folder is always safe. Without a
usable cache (no home folder, a read-only one) the .pyz extracts into a private temporary
folder for this run only.
"""

# Never evaluated annotations: an older Python must get as far as main()'s version check
# (`bool | None` raised TypeError before it on 3.9, the system python3 of macOS)
from __future__ import annotations

import atexit
import errno
import json
import os
import platform
import re
import runpy
import shutil
import site
import stat
import sys
import sysconfig
import tempfile
import time
import zipfile
from pathlib import Path

# The architecture of THIS interpreter in uv's names, as methods/common.py host_arch names the
# build's host key: platform.machine() spellings, sysconfig's on Windows, a 32-bit interpreter
ARCH = {"amd64": "x86_64", "x86_64": "x86_64", "arm64": "aarch64", "aarch64": "aarch64", "x86": "x86", "i386": "x86", "i686": "x86"}
WINDOWS_ARCH = {"win-amd64": "x86_64", "win-arm64": "aarch64", "win32": "x86"}
ARCH_32BIT = {"x86_64": "x86", "aarch64": "armv7l"}
OS = {"win32": "windows", "linux": "linux", "darwin": "macos"}
KEEP_BUILDS = 3  # the most recently started builds kept (this one included)...
MIN_AGE = 86400  # ...plus every build started in the last day
RUN_PREFIX = ".run-"  # <build>/.run-<pid>: locked while that start runs (_hold, _in_use)
# What a lock held by another process raises: flock EWOULDBLOCK, msvcrt.locking EACCES/EDEADLOCK
_BUSY = {errno.EAGAIN, errno.EWOULDBLOCK, errno.EACCES, getattr(errno, "EDEADLOCK", errno.EDEADLK)}
_running = {}  # the open, locked run file of this process (kept for its whole life)


def _arch() -> str:
    """The interpreter's architecture, not the machine's: on Windows platform.machine() asks WMI
    for the native CPU (an x64 Python on Windows on ARM said aarch64 and missed its x86_64 wheels),
    and a 32-bit Python on a 64-bit kernel (Raspberry Pi OS 32-bit) got the 64-bit name."""
    if sys.platform == "win32" and sysconfig.get_platform() in WINDOWS_ARCH:
        return WINDOWS_ARCH[sysconfig.get_platform()]
    machine = platform.machine().lower()
    arch = ARCH.get(machine, machine)
    return ARCH_32BIT.get(arch, arch) if sys.maxsize <= 2**32 else arch


def _key() -> str:
    impl = {"cpython": "cp", "pypy": "pp"}.get(sys.implementation.name, sys.implementation.name)
    return f"{impl}{sys.version_info[0]}{sys.version_info[1]}-{OS.get(sys.platform, sys.platform)}-{_arch()}"


# The extension ABI in a file name or suffix (methods/common.py ABI_RE): cpython-314[t], cp314[t]
# (Windows), pypy311-pp73. abi3 and an untagged .so/.pyd name none: the build reads their
# wheels' tags, and records an abi3 one as the key's CPython (cp314), which a 3.14t is not
ABI_RE = re.compile(r"\.(cpython-(\d+t?)|cp(\d+t?)|pypy(\d+)-(pp\d+))[-.]")


def abi_tag(name: str) -> str:
    """cp314, cp314t or pypy311_pp73 (as wheel tags name them), "" when `name` carries none."""
    m = ABI_RE.search(name)
    if not m:
        return ""
    return f"cp{m.group(2) or m.group(3)}" if m.group(4) is None else f"pypy{m.group(4)}_{m.group(5)}"


def _abi() -> str:
    """The extension ABI of THIS interpreter: its key does not tell PyPy 7.3 (pp73) from PyPy 8
    (pp80), nor CPython 3.14 from its free-threaded build (3.14t)."""
    return abi_tag(sysconfig.get_config_var("EXT_SUFFIX") or "")


def _libc() -> tuple[str, str]:
    """The C library of THIS interpreter on Linux: ("glibc", "2.39"), ("musl", "") (its
    EXT_SUFFIX names it; a Python cannot tell its musl version), ("", "") for another one
    (methods/common.py this_libc names the build machine's the same way). os.confstr, never
    platform.libc_ver(), which reads the whole interpreter file where it finds no glibc."""
    try:
        libc, _, version = (os.confstr("CS_GNU_LIBC_VERSION") or "").partition(" ")
    except (AttributeError, ValueError, OSError):  # no confstr (Windows), no such name, not glibc
        libc = version = ""
    if libc == "glibc":
        return libc, version
    return ("musl", "") if "musl" in (sysconfig.get_config_var("EXT_SUFFIX") or "") else ("", "")


def _version(text: str) -> tuple[int, ...]:
    return tuple(int(x) for x in re.findall(r"[0-9]+", text)[:2])


def _meets(floor: str) -> bool:
    """Whether this machine loads what a target's wheels were built for (_pyz.json "floor", from
    their tags: methods/common.py platform_floor): "glibc 2.28" (a glibc at least that new),
    "musl", "glibc" (wheels built on a glibc machine), "macos 13.0" (at least that macOS), ""
    (anything). A key does not tell glibc from musl, nor the versions."""
    family, _, version = floor.partition(" ")
    if not family:
        return True
    if family == "macos":
        have = platform.mac_ver()[0]
        if have.startswith("10.16"):
            return True  # a Python built with an old SDK names any macOS from 11 on so: unknown
    else:
        libc, have = _libc()
        if libc != family:
            return False
    return not version or _version(have) >= _version(version)


def _machine() -> str:
    """What _meets compared, for the refusal: glibc 2.39, musl, macos 15.1."""
    if sys.platform == "darwin":
        return f"macos {platform.mac_ver()[0]}"
    return " ".join(_libc()).strip() or "no glibc"


def _cache_root(name: str) -> Path:
    if sys.platform == "win32":
        base = Path(os.environ.get("LOCALAPPDATA") or Path.home() / "AppData" / "Local")
    elif sys.platform == "darwin":
        base = Path.home() / "Library" / "Caches"
    else:
        xdg = os.environ.get("XDG_CACHE_HOME", "")
        base = Path(xdg) if os.path.isabs(xdg) else Path.home() / ".cache"  # XDG: a relative value is ignored
    return base / name / "pyz"


def _discard(folder: Path) -> None:
    """Move a folder out of the way (atomic rename), then delete it."""
    stale = Path(tempfile.mkdtemp(prefix=".stale-", dir=folder.parent))
    try:
        os.replace(folder, stale / "old")
    except OSError:
        pass
    shutil.rmtree(stale, ignore_errors=True)


def _executable(info: zipfile.ZipInfo) -> bool:
    """Whether a member is a regular file with an x bit in its (Unix) mode."""
    mode = info.external_attr >> 16
    return bool(mode and stat.S_ISREG(mode) and mode & 0o111)


def _extract(archive: zipfile.ZipFile, prefixes: list[str], dest: Path) -> None:
    """Extract atomically (temporary folder + rename): safe with concurrent startups. A folder
    left without its .complete marker (an interrupted prune, a DLL that was still loaded) is
    moved aside and replaced. Executables keep their x bit (a helper script of the app, a
    dependency's binary such as ruff's bin/ruff)."""
    if (dest / ".complete").is_file():
        return
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = Path(tempfile.mkdtemp(prefix=".tmp-", dir=dest.parent))
    try:
        for prefix in prefixes:
            for info in archive.infolist():
                member = info.filename
                if member.startswith(prefix) and not member.endswith("/"):
                    target = tmp / member[len(prefix) :]
                    target.parent.mkdir(parents=True, exist_ok=True)
                    with archive.open(info) as src, open(target, "wb") as out:
                        shutil.copyfileobj(src, out)
                    if os.name != "nt" and _executable(info):
                        mode = os.stat(target).st_mode  # what open() gave it under the umask
                        os.chmod(target, mode | (mode & 0o444) >> 2)
        (tmp / ".complete").write_text("ok")
        for attempt in range(2):
            try:
                os.replace(tmp, dest)
                return
            except OSError:
                if (dest / ".complete").is_file():
                    return  # another start of the same build won the race
                if attempt:
                    raise
                _discard(dest)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def _lock(fd: int) -> bool | None:
    """Lock the first byte of an open file without waiting (the OS releases the lock when its
    process ends, however it ends): True, False when another process holds it, None when this
    file system cannot lock."""
    try:
        if sys.platform == "win32":
            import msvcrt

            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
        else:
            import fcntl

            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError as e:
        return False if e.errno in _BUSY else None
    return True


def _hold(build: Path) -> None:
    """Mark the build as in use for the life of this process: a lock on <build>/.run-<pid>.
    Best effort: without it the build is only protected for a day (MIN_AGE)."""
    run = build / f"{RUN_PREFIX}{os.getpid()}"
    try:
        fd = os.open(run, os.O_RDWR | os.O_CREAT, 0o600)
    except OSError:
        return
    if not _lock(fd):  # None: no locks here (MIN_AGE still protects it for a day)
        os.close(fd)
        return
    _running.update(fd=fd, path=run, pid=os.getpid())
    atexit.register(_release)


def _release() -> None:
    """At exit: drop this process's run file (a forked child that exits keeps its parent's)."""
    if _running.get("pid") != os.getpid():
        return
    try:
        if sys.platform == "win32":
            import msvcrt

            os.lseek(_running["fd"], 0, os.SEEK_SET)
            msvcrt.locking(_running["fd"], msvcrt.LK_UNLCK, 1)
        os.close(_running["fd"])
        os.unlink(_running["path"])
    except OSError:
        pass


def _in_use(build: Path) -> bool:
    """Whether a running start holds the lock of one of the build's run files. A run file whose
    lock is free was left by a start that was killed: it goes."""
    try:
        runs = [p for p in build.iterdir() if p.name.startswith(RUN_PREFIX)]
    except OSError:
        return False
    for run in runs:
        try:
            fd = os.open(run, os.O_RDWR)
        except OSError:
            continue  # its start just ended and removed it
        try:
            locked = _lock(fd)
            if locked is False:
                return True
            if locked is None:
                continue  # cannot tell: MIN_AGE decides, as for a build without run files
            if sys.platform == "win32":
                import msvcrt

                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
        except OSError:
            pass
        finally:
            os.close(fd)
        try:
            run.unlink()
        except OSError:
            pass
    return False


def _prune_old(root: Path, keep: str) -> None:
    """Delete the builds that were started least recently (main touches a build on every start),
    except `keep`, the newest ones, any build started in the last day and any build a running
    start holds (_in_use)."""
    try:
        entries = list(root.iterdir())
    except OSError:
        return
    builds = []
    for path in entries:
        if path.name.startswith(".") or path.name == keep:
            continue
        try:
            if path.is_dir():
                builds.append((path.stat().st_mtime, path))
        except OSError:
            continue  # deleted meanwhile by another start
    builds.sort()
    limit = time.time() - MIN_AGE
    for mtime, old in builds[: max(len(builds) - (KEEP_BUILDS - 1), 0)]:
        if mtime > limit or _in_use(old):
            continue
        # The markers first: an interrupted delete then reads as incomplete and is re-extracted
        for marker in old.glob("*/.complete"):
            try:
                marker.unlink()
            except OSError:
                pass
        shutil.rmtree(old, ignore_errors=True)


def _prepend_sitedir(path: Path) -> None:
    """Like site.addsitedir (it also processes the .pth files), but at the FRONT of sys.path:
    the locked dependencies in lib/ must win over packages installed in this Python."""
    before = list(sys.path)
    site.addsitedir(str(path))
    added = [p for p in sys.path if p not in before]
    sys.path[:] = added + before


def main() -> None:
    pyz = Path(__file__).resolve().parent
    with zipfile.ZipFile(pyz) as archive:
        info = json.loads(archive.read("_pyz.json"))
        need = tuple(info["min_python"])
        if sys.version_info[:2] < need:
            sys.exit(f"{info['name']}: needs Python {need[0]}.{need[1]} or newer (you have {platform.python_version()})")
        key = _key()
        abis = info.get("abi") or {}  # the extension ABIs of each target's binaries
        floors = info.get("floor") or {}  # what each target's wheels need of the machine
        mine = _abi()
        if key in info["targets"] and (not abis.get(key) or not mine or mine in abis[key]) and _meets(floors.get(key, "")):
            flavour, prefixes = key, ["common/", f"targets/{key}/"]
        elif info["pure"]:
            flavour, prefixes = "pure", ["common/"]  # the .py of a compiled module works everywhere
        else:
            facts = {t: [*abis.get(t, []), *([floors[t]] if floors.get(t) else [])] for t in info["targets"]}
            built = [t + (f" ({', '.join(facts[t])})" if facts[t] else "") for t in info["targets"]]
            here = [key, *([mine] if key in info["targets"] and mine else []), *([_machine()] if floors.get(key) else [])]
            sys.exit(
                f"{info['name']}: this .pyz has no build for this interpreter and platform ({', '.join(here)}).\n"
                f"  Built for: {', '.join(built)}"
            )
        cached = True
        try:
            root = _cache_root(info["name"])
            dest = root / info["build_id"] / flavour
            _extract(archive, prefixes, dest)
        except (OSError, RuntimeError):
            # No home folder (a random UID in a container) or a read-only cache (a service
            # user): a private folder for this run only (mkdtemp: unique name, mode 0700; a
            # predictable shared path could be planted by another user)
            cached = False
            root = Path(tempfile.mkdtemp(prefix=f"{info['name']}-pyz-"))
            atexit.register(shutil.rmtree, root, True)
            dest = root / info["build_id"] / flavour
            _extract(archive, prefixes, dest)
    if cached:
        _hold(dest.parent)  # while this process runs, no other start deletes its build
        try:
            os.utime(dest.parent)  # started now: the prune removes the least recently started builds
        except OSError:
            pass
        _prune_old(root, info["build_id"])

    app = dest / "app"
    if (dest / "lib").is_dir():
        _prepend_sitedir(dest / "lib")
    sys.path.insert(0, str(app))
    os.environ["PYTEMPLATE_ASSETS"] = str(app / "assets")  # this app's: an inherited one names another app's
    sys.argv[0] = str(app / "main.py")
    runpy.run_path(str(app / "main.py"), run_name="__main__")


main()
